import os,re
p=os.path.expanduser('~/kinship-cases/komarova/tree.html'); s=open(p,encoding='utf-8').read()
def app(cid,html):
    global s
    i=s.index(f'id="{cid}"'); j=s.index('</details>',i); k=s.rindex('</div>',i,j)
    s=s[:k]+html+s[k:]
app('egor','<p><b>Семья брата Фёдора (сверено 02.11).</b> Метрика 1904 года (ЦГА Москвы 203-780-3264, скан 319, №47, по изображению): 26 ноября 1904 (ст. ст.) у «деревни Телешева крестьянина Ѳедора Петрова Комарова и его законной жены Маріи Васильевой» родился Василий. Крёстный — Василий Васильевич Крайнов из Оладьина, муж Анны Петровны Комаровой (сестры Фёдора, брак 1903), а сам Фёдор крестил детей Крайновых. Такое взаимное кумовство — сильный довод, что это тот же Фёдор 1883 года, брат Егора. Прежняя запись «брак Фёдора в 1905 году с Татьяной Мухановой» оказалась ошибкой: в той метрике Фёдор и девица Татьяна — крёстные, а не жених и невеста. Вероятно, это тот самый Василий Фёдорович Комаров 1904 года из Телешова, ополченец 4-й дивизии народного ополчения: попал в плен 5 октября 1941 года под Ельней, умер в шталаге IV B 19 февраля 1942 года (ОБД «Мемориал» 300220441, 1150620862; жена Анастасия). Совпадают имя, отчество, год, деревня и число 26.11; слово «вероятно» остаётся, пока нет документа, прямо связывающего военного с метрикой.</p>')
s=s.replace('{ id: "s-fedor83",  sib: "egor",   x: 70,   n: "Фёдор", s: "1883–1920",','{ id: "s-fedor83",  sib: "egor",   x: 70,   n: "Фёдор", s: "1883–1920 · сын Василий",')
s=s.replace('{ id: "s-anna85",   sib: "egor",   x: 206,  n: "Анна", s: "род. 1885",','{ id: "s-anna85",   sib: "egor",   x: 206,  n: "Анна", s: "1885 · жена Крайнова",')
app('fedor','<p><b>Уточнение района (02.11).</b> По справочнику ГАКО Репецкая Плата с 1935 года в Мантуровском районе — события 1941–1943 искать в его фондах. Есть докладная Мантуровского райисполкома о зверствах оккупантов от 8 мая 1943 года (ГАКО Р-3605-1-269, л.15–19 об.), но её текст не опубликован онлайн: упоминается ли там Репецкая Плата или Снимщиковы — неизвестно. Ранние советские списки — фонд Верхосемского волисполкома (ГАКО Р-1221, 1919–1924), доступен в читальном зале.</p>')
app('fekla','<p><b>Резерв для ранних поколений (02.11).</b> Найдены внутренние росписи многоприходных книг Дмитриевского уезда, где есть Георгиевская церковь Пробожьего Поля: ГАКО 217-1-980 (1841) и 217-1-967 (1833–1834). Пригодятся, когда будет известен отец Николая Тимофеевича.</p>')
app('pavel','<p><b>Красиловка, 1876 (по внешнему отчёту, 02.11).</b> Книга Покровской церкви Красиловки за 1876 год лежит в деле ЦДІАК 127-1078-2750 (раньше было 2761), FamilySearch DGS 112318922, изображения 188–213; браки прочитаны не полностью. Брак Даниила Коритника там пока не найден, но и не исключён.</p>')
open(p,'w',encoding='utf-8').write(s); print('ok', s.count('сын Василий'), s.count('жена Крайнова'))
